  const [data, setData] = useState(null);
}

// Correct: React component
function Component() {
  const [data, setData] = useState(null);
  return <div>{data}</div>;
}

// Correct: custom Hook
function useData() {
  const [data, setData] = useState(null);
  return { data, setData };
}

